\label{thm:completion}
For every $t<0$, the metric space $(Z'_t,d_t^{Z'})$ is the metric
completion of $(R'_t,d_{g_t^{Z'}})$. In particular, $d_t^{Z'}$ is
finite-valued, and $(Z'_t,d_t^{Z'})$ is a proper length space.
If $X^{z'}$ is the metric soliton associated with $z'$, its canonical
embedding satisfies
\begin{equation}
 \iota_{z'}\bigl(X^{z'}_{(-\infty,0)}\bigr)
       =Z'_{(-\infty,0)}.
 \label{eq:surjectivity}
\end{equation}

\label{lem:cutoff-package}
There are smooth functions $\eta_\rho$ on the regular negative-time
spacetime, taking values in $[0,1]$, such that
\begin{equation}
 \begin{gathered}
 \eta_\rho>0\ \Longrightarrow\ r_{\operatorname{Rm}}\ge\rho,\qquad
 \eta_\rho=1\text{ on }\{r_{\operatorname{Rm}}\ge2\rho\},\\
 \rho|\nabla\eta_\rho|+
 \rho^2\bigl(|\partial_{\mathfrak t'}\eta_\rho|+|\nabla^2\eta_\rho|\bigr)
       \le C.
 \end{gathered}
 \label{eq:singular-cutoffs}
\end{equation}
Their supports on bounded regions of compact negative-time slabs
are relatively compact in the regular spacetime. For every
$\theta>0$, every compact interval $J\Subset(-\infty,0)$, and
every bounded spacetime region $Q\subset Z'_J$, we have, for all
sufficiently small $\rho>0$,
\begin{equation}
 \begin{split}
 \int_J\int_{Q_t\cap\{r_{\operatorname{Rm}}<2\rho\}}\,\mathrm d V_{g_t^{Z'}}\,\mathrm d t
       &\le C_{Q,J,\theta}\rho^{4-\theta},\\
 \sup_{t\in J}\operatorname{Vol}_{g_t^{Z'}}\bigl(Q_t\cap\{r_{\operatorname{Rm}}<2\rho\}\bigr)
       &\le C_{Q,J,\theta}\rho^{4-\theta}.
 \end{split}
 \label{eq:parabolic-bad-volume}
\end{equation}
Here $Q_t=Q\capR'_t$.
On the reference slice, for $A\ge1$,
\begin{equation}
 \operatorname{Vol}_g\bigl(B_g(p,A)\cap\{r_{\operatorname{Rm}}<2\rho\}\bigr)
       \le C_{A,\theta}\rho^{4-\theta}.
 \label{eq:slice-bad-volume}
\end{equation}
Finally, for every $J\Subset(-\infty,0)$ there is $C_J<\infty$
such that, for $A\ge2$,
\begin{equation}
 \sup_{t\in J}\operatorname{Vol}_{g_t^{Z'}}\{f\le A^2\}\le C_J A^n.
 \label{eq:sublevel-volume}
\end{equation}

\label{def:subcritical}
A function $u$ on $R'_J$, for $J\Subset(-\infty,0)$, has
\emph{Gaussian-subcritical growth} if, for every $\epsilon>0$, there is
$C_{J,\epsilon}<\infty$ such that
\begin{equation}
 |u(q)|\le C_{J,\epsilon}e^{\epsilon f(q)}\qquad(q\inR'_J).
 \label{eq:subcritical-growth}
\end{equation}
By \eqref{eq:slab-potential}, this is equivalently growth of order
$\exp(o(d_{g_t^{Z'}}(p_t,\cdot)^2))$, uniformly on $J$.
In particular, every polynomial-growth function satisfies this
condition.

\label{thm:representation}
Let $a<b<0$ and let
\[
 u\in C^0(R'_{[a,b]})\cap C^\infty(R'_{(a,b]})
\]
satisfy $(\partial_{\mathfrak t'}-\Delta)u=0$ and
\eqref{eq:subcritical-growth} on $[a,b]$. For every
$q\inR'_t$, $a<t\le b$,
\begin{equation}
 u(q)=\int_{R'_a}u(y)\,\mathrm d\nu_{q;a}(y).
 \label{eq:heat-representation}
\end{equation}

\label{lem:kernel-decay}
For some $c,C>0$,
\begin{equation}
 K(y)\le Ce^{-cf(y)}\qquad(y\inR'_s,\ s\in I).
 \label{eq:kernel-potential-decay}
\end{equation}
Moreover, after decreasing $c$, for every $\epsilon>0$,
\begin{equation}
 \begin{split}
 |\nabla u|(y)&\le C_\epsilon(1+r_{\operatorname{Rm}}(y)^{-1})e^{\epsilon f(y)},\\
 |\nabla K|(y)&\le C(1+r_{\operatorname{Rm}}(y)^{-1})e^{-cf(y)}.
 \end{split}
 \label{eq:gradient-envelopes}
\end{equation}

\label{cor:moment}
For $s<t<0$ and $q\inR'_t$,
\[
 |t|\left(f(q)-\frac n2\right)
 =|s|\int_{R'_s}\left(f(y)-\frac n2\right)\,\mathrm d\nu_{q;s}(y).
\]
Equivalently,
\begin{equation}
 \int_{R'_s}f(y)\,\mathrm d\nu_{q;s}(y)
 =\frac{|t|}{|s|}f(q)
   +\left(1-\frac{|t|}{|s|}\right)\frac n2.
 \label{eq:moment-solved}
\end{equation}

\label{lem:modified-time}
Let $J\Subset(-\infty,0)$ and $A<\infty$. Suppose $q_t$ is a
trajectory of $\partial_{\mathfrak t'}-\nabla f$ with $f(q_t)\le A$.
For $s,t\in J$ sufficiently close,
\begin{equation}
 d^*(q_s,q_t)\le C(n,Y,J,A)\sqrt{|t-s|}.
 \label{eq:modified-time-distance}
\end{equation}

\label{thm:comparison}
There is $C=C(n)>1$ such that, for every $\tau>0$ and
$q\in Z'_{-\tau}$,
\begin{equation}
 C^{-1}\bigl(\sqrt\tau+d_{-\tau}^{Z'}(p_{-\tau},q)\bigr)
 \le d_{Z'}(z',q)
 \le C\bigl(\sqrt\tau+d_{-\tau}^{Z'}(p_{-\tau},q)\bigr).
 \label{eq:radial-comparison}
\end{equation}
The continuous extension of $f$ to $Z'_{-\tau}$ satisfies
\begin{equation}
 C^{-1}\frac{d_{Z'}(z',q)^2}{\tau}
 \le 1+f(q)\le C\frac{d_{Z'}(z',q)^2}{\tau}.
 \label{eq:potential-spacetime}
\end{equation}
In particular, for $r\ge1$,
\begin{equation}
 \begin{split}
 B_{d_{Z'}}(z',r)\cap Z'_{-1}
       &\subset B_{d_{-1}^{Z'}}(p,Cr),\\
 B_{d_{-1}^{Z'}}(p,r)
       &\subset B_{d_{Z'}}(z',Cr).
 \end{split}
 \label{eq:ball-comparison}
\end{equation}

\label{prop:action-conjugacy}
Set
\[
 s(\tau)=2(a^{-1/2}-\tau^{-1/2}),\qquad
 S=s(b),\qquad \gamma(s)=z(\tau(s)).
\]
Then
\begin{equation}
 A_{a,b}(\beta)
 =2\sqrt b\,f(\gamma(S))-2\sqrt a\,f(\gamma(0))
       +\int_0^S|\dot\gamma|_g^2\,\mathrm d s.
 \label{eq:action-conjugacy}
\end{equation}

\label{prop:jacobian-identity}
Along each minimizing $L$-geodesic in the normal region,
the function
\begin{equation}
 Z=-\log J+\ell+\frac n2\log\tau
 \label{eq:jacobian-Z}
\end{equation}
satisfies
\begin{equation}
 D^2Z+\frac3{2\tau}D Z
       =\left|\mathrm{Ric}+\nabla^2\ell-\frac{g(\tau)}{2\tau}\right|^2\ge0.
 \label{eq:jacobian-identity}
\end{equation}
In particular, $\tau^{3/2}D Z$ is nondecreasing.

\label{lem:initial-cap}
There are $h>0$, $\theta\in(0,h)$, and $V_0,C_0<\infty$, independent
of large $i$ and of the minimizing curve, such that these curves
remain in a fixed compact regular coordinate cap on $[1,1+h]$,
$|V_i(1)|\le V_0$, and
\begin{equation}
 D Z_i(v,1+\theta)\ge-C_0.
 \label{eq:initial-Z}
\end{equation}

\label{prop:jacobian-comparison}
There is $C_J<\infty$ such that every minimizing
$L$-geodesic in the normal region satisfying \eqref{eq:uniform-action-bound} obeys
\begin{equation}
 J_i(v,4)\le C_J J_i(v,\tau)
       \qquad(1+\theta\le\tau<4).
 \label{eq:jacobian-comparison}
\end{equation}
The constant depends only on $n$, $A_0$, $\theta$, and the uniform
geometry of the initial cap.

\label{thm:quantitative}
There are $L,C<\infty$ and $\xi_0>0$ such that, for every
$0<\xi<\xi_0$, there is a compact set $D_\xi\SubsetR'_{-1}$ with
\begin{equation}
 \{x\}\cup K\subset\operatorname{int}_{R'_{-1}}D_\xi,
 \qquad D_\xi\subset\{2\sqrt f\le L+1\}\cap\{r_{\operatorname{Rm}}\ge\xi\},
 \label{eq:Dxi-containment}
\end{equation}
and
\begin{equation}
 \operatorname{Vol}_g\bigl(K\setminus G_x(D_\xi)\bigr)\le C\xi^{3-\epsilon}.
 \label{eq:quantitative-attainment}
\end{equation}

\label{lem:last-entry-localization}
There are $R_*,\delta_a,\delta_b>0$, independent of $\xi$, such that
for sufficiently large $i$ after $\xi$ is fixed,
\begin{equation}
 r(z_i(\tau))\le R_*\quad(\bar\tau\le\tau\le4),\qquad
 1+\delta_a\le\bar\tau\le4-\delta_b.
 \label{eq:last-entry-localization}
\end{equation}
The outer radius $L$ can be fixed so that a last contact on
$\partial_{\rm out}\Omega_\xi$ is impossible. The initial
$\theta$ in \eqref{eq:jacobian-comparison} can be chosen with
$\theta<\delta_a$.

\label{lem:relative-speed}
There is $C_V<\infty$, independent of $\xi$, such that every bad
minimizing curve satisfies
\begin{equation}
 |\dot\gamma_i|_g\le C_V\quad(\bar s\le s\le1),\qquad
 |V_i-U_i|_{g_i(-\bar\tau)}\le C_V'
 \label{eq:relative-speed}
\end{equation}
at the last-entry point, for all sufficiently large $i$ after
$\xi$ is fixed.

\label{lem:flux}
On the part of this track contained in the normal region, the
absolute $n$-dimensional Jacobian of the restricted projection is
\begin{equation}
 \operatorname{Jac} P=\frac{J(v,4)}{J(v,\tau)}
                     |\langle V-U,\nu\rangle_{g(\tau)}|.
 \label{eq:flux-jacobian}
\end{equation}
Consequently, for a measurable subset $H$ of the track contained
in the normal region,
\begin{equation}
 \operatorname{Vol}_{g(4)}(P(H))
 \le\int_H\frac{J(v,4)}{J(v,\tau)}
              |\langle V-U,\nu\rangle|\,\mathrm d\sigma_\tau\,\mathrm d\tau.
 \label{eq:flux-inequality}
\end{equation}

\label{prop:avoidance}
For $0<\xi<\xi_0$ and $i\ge i_0(\xi)$,
\begin{equation}
 \operatorname{Vol}_g(B_{i,\xi})\le C\xi^{3-\epsilon},
 \label{eq:avoidance}
\end{equation}
where $C$ is independent of $i$ and $\xi$.

\label{lem:good-subsequence}
If $\xi>0$ is fixed and $y\in K$ satisfies $y\notin B_{i,\xi}$
for infinitely many $i$, then $y\in G_x(D_\xi)$.

\label{prop:sharp-potential}
The function $f$ attains its minimum at some $p\in X$, which need
not belong to $R$, and $0\le f(p)\le n/2$.
For every such minimum point and every $x\in X$,
\begin{equation}
 \frac14\bigl(d(p,x)-5n\bigr)_+^2
 \le f(x)\le
 \frac14\bigl(d(p,x)+\sqrt{2n}\bigr)^2,
 \label{eq:sharp-potential}
\end{equation}
where $a_+=\max\{a,0\}$.

\label{lem:local-volume-segment}
For every $L>0$ there is $C=C(n,L)$ with the following properties.
If $0<r_1<r_2$ and $B_d(q,r_2)\subset B_d(p,L)$, then
\begin{equation}
 \frac{\mathfrak m(B_d(q,r_2))}{\mathfrak m(B_d(q,r_1))}
       \le e^{C(r_2-r_1)}\left(\frac{r_2}{r_1}\right)^n.
 \label{eq:local-volume-comparison}
\end{equation}
If $A_1,A_2\subset B_d(q,r)\capR$ are measurable and
$B_d(q,r)\subset B_d(p,L)$, then every nonnegative measurable
function $a$ on $B_d(q,3r)\capR$ satisfies
\begin{equation}
 \begin{split}
 &\int_{A_1\times A_2}\int_0^{d(x,y)}a(\gamma_{xy}(s))\,\mathrm d s
                          \,\mathrm d\mathfrak m(x)\,\mathrm d\mathfrak m(y)\\
 &\hspace{1cm}\le Cr\bigl(\mathfrak m(A_1)+\mathfrak m(A_2)\bigr)
                          \int_{B_d(q,3r)}a\,\mathrm d\mathfrak m,
 \end{split}
 \label{eq:local-segment-inequality}
\end{equation}
where $\gamma_{xy}$ is the unique regular minimizing geodesic for almost
every pair $(x,y)$.

\label{prop:local-functional}
For every $L>0$ there is $C=C(n,L)$ such that, for every
$B=B_d(q,r)\subset B_d(p,L)$ and
$u\in W^{1,2}_{\mathrm{loc}}(X,d,\mathfrak m)$,
\begin{equation}
 \fint_B|u-u_{B,\mathfrak m}|^2\,\mathrm d\mathfrak m
       \le Cr^2\fint_B|\nabla u|^2\,\mathrm d\mathfrak m.
 \label{eq:local-poincare}
\end{equation}
If $n>2$, then also
\begin{equation}
 \left(\fint_B|u|^{\frac{2n}{n-2}}\,\mathrm d\mathfrak m\right)^{\frac{n-2}{n}}
       \le C\fint_B\bigl(r^2|\nabla u|^2+|u|^2\bigr)\,\mathrm d\mathfrak m.
 \label{eq:local-sobolev}
\end{equation}
Both statements hold with $\mathrm dV_g$ in place of $\,\mathrm d\mathfrak m$
and with the corresponding averages, after changing $C(n,L)$.

\label{lem:entropy-density}
For every $z\in X$ and every tangent cone $C$ at $z$,
\begin{equation}
 N_z(0)=\log\vartheta(C).
 \label{eq:entropy-density}
\end{equation}
In particular, the right-hand side is independent of the choice
of tangent cone. There is $\epsilon_n>0$ such that
\begin{equation}
 z\inS\quad\Longrightarrow\quad
 \vartheta(C)\le e^{-\epsilon_n}<1.
 \label{eq:singular-density-gap}
\end{equation}
A point of $X$ is regular if and only if it has a Euclidean tangent
cone.

\label{lem:global-bochner}
Let $v$ be bounded and Lipschitz on $X$, and set $h=P_sv$ for
$s>0$. Then $|\nabla^2h|\in L^2_{\mathrm{loc}}(X,\mathfrak m)$
and $|\nabla h|^2\in W^{1,2}_{\mathrm{loc}}(X,d,\mathfrak m)$.
Moreover,
\begin{equation}
 (\partial_s-\Delta_f)|\nabla h|^2
       \le-2|\nabla^2h|^2-|\nabla h|^2
 \label{eq:weighted-Bochner}
\end{equation}
in the distributional sense on $X\times(0,\infty)$. The Hessian is computed on
$R$ and extended by zero across $S$.

\label{lem:heat-approximation}
There are $C$ and $r_0>0$, uniform in the parameters just fixed,
such that, for $0<r<r_0$, the following hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item On the buffered region, for small $s>0$,
\begin{equation}
 |h_s^\pm-d^\pm|\le Cs+e,
 \qquad |\nabla h_s^\pm|^2\le1+Cs.
 \label{eq:heat-pointwise}
\end{equation}
For $t\in[\delta,1-\delta]$,
\begin{equation}
 \fint_{B_d(\gamma(t),r)}e\,\mathrm d\mathfrak m\le Cr^2.
 \label{eq:mean-excess}
\end{equation}
\item There is a single $s_r\in[r^2/2,2r^2]$ for which
\begin{equation}
 \int_\delta^{1-\delta}
 \fint_{B_d(\gamma(t),5r)}
 \bigl(|\nabla^2h_{s_r}^-|^2+|\nabla^2h_{s_r}^+|^2\bigr)
             \,\mathrm d\mathfrak m\,\mathrm d t\le C.
 \label{eq:integrated-hessian}
\end{equation}
\item Let $\sigma_z$ be a unit-speed regular minimizing geodesic from $q_-$ to a point
$z$ in the region under consideration. For every subinterval $J$
with $\sigma_z(J)$ contained in the buffered region,
\begin{equation}
 \int_J|\nabla h_{s_r}^--\nabla d^-|^2(\sigma_z(t))\,\mathrm d t
                    \le C\bigl(e(z)+r^2\bigr).
 \label{eq:radial-energy}
\end{equation}
In particular, on a subinterval of length $v$ the corresponding
$L^1$ error is at most $C\sqrt v(\sqrt{e(z)}+r)$.
For a unit-speed regular minimizing geodesic from $q_+$ the analogous estimates hold
with $\nabla h_{s_r}^+-\nabla d^+$.
\end{enumerate}
